import datetime
def age_on(birth, on):
    b = datetime.date.fromisoformat(birth)
    d = datetime.date.fromisoformat(on)
    if d < b:
        raise ValueError('before birth')
    years = d.year - b.year
    try:
        birthday = b.replace(year=d.year)
    except ValueError:
        birthday = datetime.date(d.year, 3, 1)
    if d < birthday:
        years -= 1
    return years

